for path in base.glob('raw_service_reports/day_*/*.txt'):
 d=dict(line.split(': ',1) for line in path.read_text().splitlines() if ': ' in line)
 rows.append([d['WORK ORDER'],int(d['DAY']),d['MACHINE'],d['TECHNICIAN'],d['STARTED'],d['COMPLETED']])
